"""
    This is a function to ensure that there is at least 2 digits to each input.

    It adds a leading or an ending zero to each single-digit entry,
    all values will be turned to str or tuples containing str to maintain the format.

    Any item not of int or float will be skipped.

    str.zfill() is a good alternative, but not so much for decimals.

    Parameters
    -------

    h: dict
        this is the dict of each product.

    k: str
        This is the key of each dict entry.

    i: str/int/float
        This is the value of each entry, which does not stay standard.

    Returns
    -------
    : list
    """
def minimum_format_ensurer(products: Any) -> object {
    for h in products {
        for (k, i) in h.items() {
            if (k == 'pQua') {
                continue;
            }
            if ((`type(i) is int) and (len(str(i)) == 1)) {
                i = '0' + str(i);
            } elif (`type(i) is float) {
                AED = str(i).split('.')[0];
                FIL = str(i).split('.')[-1];
                if (len(AED) == 1) {
                    AED = '0' + AED;
                }
                if (len(FIL) == 1) {
                    FIL = FIL + '0';
                }
                i = (AED, FIL);
            } else {
                continue;
            }
            h[k] = i;
        }
    }
    return products;
}

test_blocks:
test "t0" {
    assert (
        minimum_format_ensurer(
            [
                {'name': 'A', 'value': 1.2},
                {'name': 'B', 'value': 1},
                {'name': 'C', 'value': 0}
            ]
        )
        == [
            {'name': 'A', 'value': ('01', '20')},
            {'name': 'B', 'value': '01'},
            {'name': 'C', 'value': '00'}
        ]
    );;
}

test "t1" {
    assert (
        minimum_format_ensurer([{'a': 1, 'b': 2, 'c': 3, 'd': 4, 'e': 5.0}])
        == [{'a': '01', 'b': '02', 'c': '03', 'd': '04', 'e': ('05', '00')}]
    ) , 'D';;
}

test "t2" {
    assert (
        minimum_format_ensurer([{'AED': 1, 'FIL': 2}, {'AED': 3, 'FIL': 4}])
        == [{'AED': '01', 'FIL': '02'}, {'AED': '03', 'FIL': '04'}]
    );;
}

test "t3" {
    assert (
        minimum_format_ensurer([{'a': 1, 'b': 2, 'c': 3, 'd': 4, 'e': 5}])
        == [{'a': '01', 'b': '02', 'c': '03', 'd': '04', 'e': '05'}]
    ) , 'A';;
}

test "t4" {
    assert (
        minimum_format_ensurer(
            [
                {'pNam': 'The Great Book', 'pPri': 123.45, 'pQua': (2, '200')},
                {'pNam': 'The Second Great Book', 'pPri': 678.9, 'pQua': (1, '1000')}
            ]
        )
        == [
            {'pNam': 'The Great Book', 'pPri': ('123', '45'), 'pQua': (2, '200')},
            {
                'pNam': 'The Second Great Book',
                'pPri': ('678', '90'),
                'pQua': (1, '1000')
            }
        ]
    );;
}

test "t5" {
    assert (
        minimum_format_ensurer(
            [
                {'pNam': 'The Great Book', 'pPri': 999.99, 'pQua': (2, '200')},
                {'pNam': 'The Second Great Book', 'pPri': 888.88, 'pQua': (1, '1000')}
            ]
        )
        == [
            {'pNam': 'The Great Book', 'pPri': ('999', '99'), 'pQua': (2, '200')},
            {
                'pNam': 'The Second Great Book',
                'pPri': ('888', '88'),
                'pQua': (1, '1000')
            }
        ]
    );;
}

test "t6" {
    assert (
        minimum_format_ensurer([{'a': '01', 'b': 2, 'c': 3, 'd': 4, 'e': 5}])
        == [{'a': '01', 'b': '02', 'c': '03', 'd': '04', 'e': '05'}]
    ) , 'C';;
}

test "t7" {
    assert (
        minimum_format_ensurer([{'a': 1, 'b': 2, 'c': 3, 'd': 4, 'e': 5, 'f': 1.0}])
        == [{'a': '01', 'b': '02', 'c': '03', 'd': '04', 'e': '05', 'f': ('01', '00')}]
    ) , 'B';;
}
